#include "KS/SRC/iri.h"

template<
    class RandomAccessIterator,
    class Distance,
    class T>
void __push_heap(
    RandomAccessIterator first,
    Distance hole_index,
    Distance top_index,
    T value)
{
    Distance parent = (hole_index - 1) / 2;
    while (hole_index > top_index &&
           *(first + parent) < value) {
        *(first + hole_index) =
            *(first + parent);
        hole_index = parent;
        parent = (hole_index - 1) / 2;
    }
    *(first + hole_index) = value;
}

template<
    class RandomAccessIterator,
    class Distance,
    class T>
void __adjust_heap(
    RandomAccessIterator first,
    Distance hole_index,
    Distance length,
    T value)
{
    Distance top_index = hole_index;
    Distance second_child =
        2 * hole_index + 2;
    while (second_child < length) {
        if (*(first + second_child) <
            *(first + (second_child - 1)))
            second_child--;
        *(first + hole_index) =
            *(first + second_child);
        hole_index = second_child;
        second_child =
            2 * (second_child + 1);
    }
    if (second_child == length) {
        *(first + hole_index) =
            *(first + (second_child - 1));
        hole_index = second_child - 1;
    }
    __push_heap(
        first,
        hole_index,
        top_index,
        value);
}

template void __adjust_heap(
    instance_render_info *,
    int,
    int,
    instance_render_info);
